contracts/AuditStorage.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract AuditStorage {
    struct AuditRecord {
        uint256 timestamp;
        address submitter;
        string operationType;
        string userId;
    }

    address public owner;
    mapping(address => bool) public authorizedOperators;

    mapping(bytes32 => AuditRecord) public records;
    bytes32[] public recordIndex;

    event AuditStored(bytes32 indexed hashValue, uint256 timestamp, string operationType, string userId);
    event OperatorAuthorized(address indexed operator);
    event OperatorRevoked(address indexed operator);

    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner");
        _;
    }

    modifier onlyAuthorized() {
        require(msg.sender == owner || authorizedOperators[msg.sender], "Not authorized");
        _;
    }

    constructor() {
        owner = msg.sender;
    }

    function authorizeOperator(address op) external onlyOwner {
        require(op != address(0), "Zero address");
        authorizedOperators[op] = true;
        emit OperatorAuthorized(op);
    }

    function revokeOperator(address op) external onlyOwner {
        authorizedOperators[op] = false;
        emit OperatorRevoked(op);
    }

    function storeAuditHash(bytes32 hashValue, uint256 timestamp, string memory operationType, string memory userId) public onlyAuthorized returns (bool) {
        require(records[hashValue].timestamp == 0, "Hash already exists");
        records[hashValue] = AuditRecord(timestamp, msg.sender, operationType, userId);
        recordIndex.push(hashValue);
        emit AuditStored(hashValue, timestamp, operationType, userId);
        return true;
    }

    function getTotalRecords() public view returns (uint256) {
        return recordIndex.length;
    }

    function getRecordByHash(bytes32 hashValue) public view returns (
        uint256 timestamp,
        address submitter,
        string memory operationType,
        string memory userId
    ) {
        AuditRecord memory r = records[hashValue];
        require(r.timestamp != 0, "Record not found");
        return (r.timestamp, r.submitter, r.operationType, r.userId);
    }

    function getRecordByIndex(uint256 index) public view returns (
        bytes32 hashValue,
        uint256 timestamp,
        address submitter,
        string memory operationType,
        string memory userId
    ) {
        require(index < recordIndex.length, "Index out of bounds");
        bytes32 key = recordIndex[index];
        AuditRecord memory r = records[key];
        return (key, r.timestamp, r.submitter, r.operationType, r.userId);
    }
}

contracts/FinZkTrust.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/math/Math.sol";
import "./Verifier.sol";

contract FinZkTrust is Ownable, ReentrancyGuard, AccessControl {
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");

    // Structs
    struct UserInfo {
        bytes sm2PublicKey;
        uint256 creditScore;
        uint256 loanLimit;
        bool isInitialized;
    }

    struct Loan {
        address borrower;
        uint256 amount;
        uint256 interestRate;
        uint256 startTime;
        uint256 duration;
        bool isActive;
        bool isRepaid;
    }

    struct Investment {
        address investor;
        uint256 amount;
        uint256 startTime;
        uint256 term;
        bool isActive;
    }

    struct Transaction {
        address user;
        uint256 amount;
        uint256 timestamp;
        string transactionType;
    }

    // State variables
    Verifier public verifier;
    mapping(address => UserInfo) public userInfos;
    mapping(address => Loan[]) public borrowerLoans;
    mapping(address => Investment[]) public investorInvestments;
    mapping(bytes32 => bool) public transactionHashes;
    Transaction[] public transactions;

    // Pools
    uint256 public originalPoolBalance;
    uint256 public userPoolBalance;

    // Constants
    uint256 public constant MIN_INVESTMENT_AMOUNT = 100 * 10**18; // 100 tokens
    uint256 public constant MIN_CREDIT_SCORE = 600;
    uint256 public constant MAX_LOAN_AMOUNT = 1000000 * 10**18; // 1M tokens
    uint256 public constant MIN_LOAN_DURATION = 30 days;
    uint256 public constant MAX_LOAN_DURATION = 365 days;
    uint256 public constant ZK_PROOF_EXPIRY = 24 hours;

    // Interest rate ranges based on credit score
    uint256 public constant HIGH_CREDIT_THRESHOLD = 800;
    uint256 public constant MEDIUM_CREDIT_THRESHOLD = 700;
    uint256 public constant LOW_INTEREST_RATE = 4; // 4% APR
    uint256 public constant MEDIUM_INTEREST_RATE = 6; // 6% APR
    uint256 public constant HIGH_INTEREST_RATE = 8; // 8% APR

    // Events
    event UserInitialized(address indexed user, bytes sm2PublicKey, uint256 creditScore, uint256 loanLimit);
    event LoanCreated(address indexed borrower, uint256 amount, uint256 duration, uint256 interestRate);
    event LoanRepaid(address indexed borrower, uint256 amount);
    event InvestmentCreated(address indexed investor, uint256 amount, uint256 term);
    event InvestmentRedeemed(address indexed investor, uint256 amount, uint256 interest);
    event TransactionHashRecorded(bytes32 indexed hash, address indexed user, string transactionType);
    event PoolDeposited(address indexed depositor, uint256 amount, string poolType);
    event SystemBalanceUpdated(uint256 originalPool, uint256 userPool);

    constructor(address _verifierAddress) {
        _setupRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _setupRole(ADMIN_ROLE, msg.sender);
        verifier = Verifier(_verifierAddress);
        originalPoolBalance = 10000 * 10**18; // Initial original pool balance: 10000 tokens
        userPoolBalance = 0; // Initial user pool balance: 0
    }

    // Modifiers
    modifier onlyAdmin() {
        require(hasRole(ADMIN_ROLE, msg.sender), "Caller is not an admin");
        _;
    }

    modifier userInitialized() {
        require(userInfos[msg.sender].isInitialized, "User not initialized");
        _;
    }

    modifier validLoanAmount(uint256 amount) {
        require(amount > 0 && amount <= MAX_LOAN_AMOUNT, "Invalid loan amount");
        _;
    }

    modifier validLoanDuration(uint256 duration) {
        require(
            duration >= MIN_LOAN_DURATION && duration <= MAX_LOAN_DURATION,
            "Invalid loan duration"
        );
        _;
    }

    modifier validInvestmentAmount(uint256 amount) {
        require(amount >= MIN_INVESTMENT_AMOUNT, "Investment amount too small");
        _;
    }

    // Functions
    function initializeUser(bytes calldata _sm2PublicKey, uint256 _creditScore) external onlyAdmin {
        require(_sm2PublicKey.length > 0, "SM2 public key cannot be empty");
        require(_creditScore >= 0 && _creditScore <= 1000, "Invalid credit score");

        uint256 loanLimit = calculateLoanLimit(_creditScore);

        userInfos[msg.sender] = UserInfo({
            sm2PublicKey: _sm2PublicKey,
            creditScore: _creditScore,
            loanLimit: loanLimit,
            isInitialized: true
        });

        emit UserInitialized(msg.sender, _sm2PublicKey, _creditScore, loanLimit);
    }

    function depositToPool(uint256 amount) external payable nonReentrant onlyAdmin {
        require(amount > 0, "Amount must be greater than 0");
        require(msg.value >= amount, "Insufficient funds");

        originalPoolBalance += amount;
        emit PoolDeposited(msg.sender, amount, "ORIGINAL_POOL");
        emit SystemBalanceUpdated(originalPoolBalance, userPoolBalance);
    }

    function invest(uint256 amount, uint256 term) 
        external 
        payable 
        nonReentrant 
        userInitialized 
        validInvestmentAmount(amount)
    {
        require(msg.value >= amount, "Insufficient funds");

        Investment memory newInvestment = Investment({
            investor: msg.sender,
            amount: amount,
            startTime: block.timestamp,
            term: term,
            isActive: true
        });

        investorInvestments[msg.sender].push(newInvestment);
        userPoolBalance += amount;

        emit InvestmentCreated(msg.sender, amount, term);
        emit SystemBalanceUpdated(originalPoolBalance, userPoolBalance);
    }

    function borrow(
        uint256 amount,
        uint256 duration,
        uint256[2] memory proofA,
        uint256[2][2] memory proofB,
        uint256[2] memory proofC,
        uint256[2] memory proofInput,
        bytes32 sm3Hash
    ) 
        external 
        nonReentrant 
        userInitialized 
        validLoanAmount(amount) 
        validLoanDuration(duration)
    {
        UserInfo storage userInfo = userInfos[msg.sender];
        require(userInfo.creditScore >= MIN_CREDIT_SCORE, "Insufficient credit score");
        require(amount <= userInfo.loanLimit, "Loan amount exceeds limit");

        // Verify zero-knowledge proof
        bool proofValid = verifier.verifyProof(
            msg.sender,
            proofA,
            proofB,
            proofC,
            proofInput,
            sm3Hash
        );
        require(proofValid, "Invalid zero-knowledge proof");

        // Check pool balance
        uint256 totalPoolBalance = originalPoolBalance + userPoolBalance;
        require(amount <= totalPoolBalance, "Insufficient pool balance");

        uint256 interestRate = calculateInterestRate(userInfo.creditScore);

        Loan memory newLoan = Loan({
            borrower: msg.sender,
            amount: amount,
            interestRate: interestRate,
            startTime: block.timestamp,
            duration: duration,
            isActive: true,
            isRepaid: false
        });

        borrowerLoans[msg.sender].push(newLoan);

        // Deduct from pools (priority: user pool first)
        if (amount <= userPoolBalance) {
            userPoolBalance -= amount;
        } else {
            uint256 userPoolAmount = userPoolBalance;
            userPoolBalance = 0;
            originalPoolBalance -= (amount - userPoolAmount);
        }

        emit LoanCreated(msg.sender, amount, duration, interestRate);
        emit SystemBalanceUpdated(originalPoolBalance, userPoolBalance);
    }

    function redeem(uint256 amount) external nonReentrant userInitialized {
        require(amount > 0, "Amount must be greater than 0");

        Investment[] storage investments = investorInvestments[msg.sender];
        require(investments.length > 0, "No investments found");

        uint256 totalRedeemable = 0;
        uint256 totalInterest = 0;

        // Calculate total redeemable amount (interest + principal)
        for (uint i = 0; i < investments.length; i++) {
            if (investments[i].isActive) {
                uint256 interest = calculateInvestmentInterest(investments[i]);
                totalRedeemable += investments[i].amount + interest;
                totalInterest += interest;
            }
        }

        require(amount <= totalRedeemable, "Amount exceeds redeemable balance");

        uint256 remainingAmount = amount;

        // Redeem in order: interest first, then non-today principal, then today principal
        for (uint i = 0; i < investments.length && remainingAmount > 0; i++) {
            Investment storage investment = investments[i];
            if (investment.isActive) {
                uint256 interest = calculateInvestmentInterest(investment);

                // Redeem interest first
                if (interest > 0) {
                    uint256 interestRedeem = Math.min(remainingAmount, interest);
                    remainingAmount -= interestRedeem;
                    totalInterest -= interestRedeem;
                }

                // Redeem principal if needed
                if (remainingAmount > 0) {
                    uint256 principalRedeem = Math.min(remainingAmount, investment.amount);
                    remainingAmount -= principalRedeem;
                    investment.amount -= principalRedeem;

                    if (investment.amount == 0) {
                        investment.isActive = false;
                    }
                }
            }
        }

        userPoolBalance -= (amount - totalInterest);

        emit InvestmentRedeemed(msg.sender, amount, totalInterest);
        emit SystemBalanceUpdated(originalPoolBalance, userPoolBalance);
    }

    function recordTransactionHash(bytes32 hash, string calldata transactionType) external nonReentrant userInitialized {
        require(hash != bytes32(0), "Hash cannot be empty");
        require(!transactionHashes[hash], "Hash already recorded");

        transactionHashes[hash] = true;
        emit TransactionHashRecorded(hash, msg.sender, transactionType);
    }

    function calculateLoanLimit(uint256 creditScore) public pure returns (uint256) {
        if (creditScore >= 900) {
            return 50000 * 10**18; // 50,000 tokens
        } else if (creditScore >= 800) {
            return 20000 * 10**18; // 20,000 tokens
        } else if (creditScore >= 700) {
            return 10000 * 10**18; // 10,000 tokens
        } else if (creditScore >= 600) {
            return 5000 * 10**18; // 5,000 tokens
        } else {
            return 0;
        }
    }

    function calculateInterestRate(uint256 creditScore) public pure returns (uint256) {
        if (creditScore >= HIGH_CREDIT_THRESHOLD) {
            return LOW_INTEREST_RATE;
        } else if (creditScore >= MEDIUM_CREDIT_THRESHOLD) {
            return MEDIUM_INTEREST_RATE;
        } else {
            return HIGH_INTEREST_RATE;
        }
    }

    function calculateInvestmentInterest(Investment memory investment) public view returns (uint256) {
        uint256 timeElapsed = block.timestamp - investment.startTime;
        uint256 interestRate = 8; // 8% APR for investments
        return (investment.amount * interestRate * timeElapsed) / (365 days * 100);
    }

    function getUserInfo(address user) external view returns (UserInfo memory) {
        return userInfos[user];
    }

    function getInvestorInvestments(address investor) external view returns (Investment[] memory) {
        return investorInvestments[investor];
    }

    function getPoolBalances() external view returns (uint256, uint256) {
        return (originalPoolBalance, userPoolBalance);
    }

    function isTransactionHashRecorded(bytes32 hash) external view returns (bool) {
        return transactionHashes[hash];
    }
}

contracts/TransactionHashStorage.sol.content:
// SPDX-License-Identifier: MIT
// 国密SM3+私链不可篡改+ZK零知识隐私核验三合一安全架构
// 本合约仅存储交易数据的SM3哈希摘要，原始交易数据不上链

pragma solidity ^0.8.19;

/**
 * @title TransactionHashStorage
 * @dev 交易哈希存证合约 - 用于存储关键交易信息的SM3哈希
 * 符合网络安全竞赛国密合规评分点要求
 */
contract TransactionHashStorage {

    // 交易哈希结构体
    struct TransactionHash {
        bytes32 transactionId;      // 交易唯一标识符
        bytes32 sm3Hash;           // SM3哈希值（32字节）
        uint256 timestamp;         // 区块时间戳
        string transactionType;    // 交易类型（loan/repay/credit_proof等）
        string userId;            // 用户ID
        address submitter;        // 提交者地址
    }

    // 交易ID到交易哈希的映射
    mapping(bytes32 => TransactionHash) public transactionHashes;

    // 所有交易ID数组（用于遍历和统计）
    bytes32[] public transactionIds;

    // 用户交易计数映射
    mapping(string => uint256) public userTransactionCount;

    // 合约所有者
    address public owner;

    // 事件定义
    event TransactionHashStored(
        bytes32 indexed transactionId,
        bytes32 sm3Hash,
        string transactionType,
        string userId,
        uint256 timestamp,
        address submitter
    );

    event TransactionHashVerified(
        bytes32 indexed transactionId,
        bytes32 storedHash,
        bool isValid,
        uint256 verifyTime
    );

    // 修饰器：仅合约所有者
    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner can call this function");
        _;
    }

    /**
     * @dev 构造函数
     */
    constructor() {
        owner = msg.sender;
    }

    /**
     * @dev 存储交易哈希
     * @param _transactionId 交易唯一标识符（bytes32）
     * @param _sm3Hash SM3哈希值（bytes32格式）
     * @param _transactionType 交易类型
     * @param _userId 用户ID
     */
    function storeTransactionHash(
        bytes32 _transactionId,
        bytes32 _sm3Hash,
        string calldata _transactionType,
        string calldata _userId
    ) external {
        // 验证交易ID是否已存在
        require(transactionHashes[_transactionId].timestamp == 0, "Transaction already exists");

        // 验证SM3哈希不为空
        require(_sm3Hash != bytes32(0), "SM3 hash cannot be empty");

        // 创建交易哈希记录
        TransactionHash memory newRecord = TransactionHash({
            transactionId: _transactionId,
            sm3Hash: _sm3Hash,
            timestamp: block.timestamp,
            transactionType: _transactionType,
            userId: _userId,
            submitter: msg.sender
        });

        // 存储到映射
        transactionHashes[_transactionId] = newRecord;

        // 添加到交易ID数组
        transactionIds.push(_transactionId);

        // 增加用户交易计数
        userTransactionCount[_userId]++;

        // 触发事件
        emit TransactionHashStored(
            _transactionId,
            _sm3Hash,
            _transactionType,
            _userId,
            block.timestamp,
            msg.sender
        );
    }

    /**
     * @dev 获取交易哈希
     * @param _transactionId 交易唯一标识符
     * @return TransactionHash 交易哈希记录
     */
    function getTransactionHash(bytes32 _transactionId) 
        external 
        view 
        returns (TransactionHash memory) 
    {
        require(transactionHashes[_transactionId].timestamp != 0, "Transaction not found");
        return transactionHashes[_transactionId];
    }

    /**
     * @dev 验证交易哈希
     * @param _transactionId 交易唯一标识符
     * @param _calculatedHash 计算得到的SM3哈希值
     * @return bool 验证结果
     */
    function verifyTransactionHash(
        bytes32 _transactionId,
        bytes32 _calculatedHash
    ) external returns (bool) {
        TransactionHash memory storedRecord = transactionHashes[_transactionId];

        // 检查交易是否存在
        if (storedRecord.timestamp == 0) {
            emit TransactionHashVerified(_transactionId, _calculatedHash, false, block.timestamp);
            return false;
        }

        // 比对哈希值
        bool isValid = storedRecord.sm3Hash == _calculatedHash;

        emit TransactionHashVerified(_transactionId, storedRecord.sm3Hash, isValid, block.timestamp);

        return isValid;
    }

    /**
     * @dev 获取交易总数
     * @return uint256 交易总数
     */
    function getTransactionCount() external view returns (uint256) {
        return transactionIds.length;
    }

    /**
     * @dev 获取用户的交易数量
     * @param _userId 用户ID
     * @return uint256 用户交易数量
     */
    function getUserTransactionCount(string calldata _userId) external view returns (uint256) {
        return userTransactionCount[_userId];
    }

    /**
     * @dev 批量获取交易哈希（分页查询）
     * @param _start 起始索引
     * @param _limit 查询数量
     * @return TransactionHash[] 交易哈希数组
     */
    function getTransactionHashesBatch(uint256 _start, uint256 _limit) 
        external 
        view 
        returns (TransactionHash[] memory) 
    {
        require(_start < transactionIds.length, "Start index out of bounds");

        uint256 end = _start + _limit;
        if (end > transactionIds.length) {
            end = transactionIds.length;
        }

        uint256 count = end - _start;
        TransactionHash[] memory result = new TransactionHash[](count);

        for (uint256 i = 0; i < count; i++) {
            result[i] = transactionHashes[transactionIds[_start + i]];
        }

        return result;
    }

    /**
     * @dev 检查交易是否存在
     * @param _transactionId 交易唯一标识符
     * @return bool 是否存在
     */
    function transactionExists(bytes32 _transactionId) external view returns (bool) {
        return transactionHashes[_transactionId].timestamp != 0;
    }

    /**
     * @dev 转移合约所有权
     * @param _newOwner 新所有者地址
     */
    function transferOwnership(address _newOwner) external onlyOwner {
        require(_newOwner != address(0), "New owner cannot be zero address");
        owner = _newOwner;
    }
}

contracts/UserRegistry.sol.content:
pragma solidity ^0.8.0;

contract UserRegistry {
    struct UserRecord {
        string pkHash;
        uint256 createdAt;
        uint256 updatedAt;
        bool exists;
    }

    mapping(address => UserRecord) private users;
    address[] public userIndex;

    event UserRegistered(address indexed usr, string pkHash, uint256 time);
    event UserUpdated(address indexed usr, string oldHash, string newHash, uint256 time);

    function register(string memory pkHash) public {
        require(!users[msg.sender].exists, "Already registered, use update");
        users[msg.sender] = UserRecord(pkHash, block.timestamp, block.timestamp, true);
        userIndex.push(msg.sender);
        emit UserRegistered(msg.sender, pkHash, block.timestamp);
    }

    function update(string memory newPkHash) public {
        require(users[msg.sender].exists, "Not registered yet");
        string memory oldHash = users[msg.sender].pkHash;
        users[msg.sender].pkHash = newPkHash;
        users[msg.sender].updatedAt = block.timestamp;
        emit UserUpdated(msg.sender, oldHash, newPkHash, block.timestamp);
    }

    function getUser(address usr) public view returns (
        string memory pkHash,
        uint256 createdAt,
        uint256 updatedAt
    ) {
        UserRecord memory u = users[usr];
        require(u.exists, "Not found");
        return (u.pkHash, u.createdAt, u.updatedAt);
    }

    function getTotalUsers() public view returns (uint256) {
        return userIndex.length;
    }
}

